function htmlToText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|section|article|li|h1|h2|h3|h4|h5|h6|br)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map(item => {
  const html = item.json.body || item.json.data || item.json.response || '';

  return {
    json: {
      ...item.json,
      raw_content: htmlToText(html),
      raw_length: html.length
    }
  };
});

return items.filter(item => {
  const text = item.json.raw_content || '';
  return text.length > 50;
});

return items.map(item => ({
  json: {
    site_url: item.json.site_url,
    project_name: item.json.project_name,
    source: item.json.source,
    url: item.json.url,
    raw_content: item.json.raw_content
  }
}));

const xml =
  $json.data ||
  $json.body ||
  $json.response ||
  '';

const site_url =
  $('On form submission').first().json.site_url || '';

const project_name =
  $('On form submission').first().json.project_name || '';

if (!xml || typeof xml !== 'string') {
  return [
    {
      json: {
        site_url,
        project_name,
        urls: [],
        sitemap_type: 'empty'
      }
    }
  ];
}

const matches = [...xml.matchAll(/<loc>(.*?)<\/loc>/gsi)];
const urls = matches.map(m => m[1].trim());

const sitemap_type = xml.includes('<sitemapindex')
  ? 'index'
  : 'urlset';

return [
  {
    json: {
      site_url,
      project_name,
      xml_preview: xml.slice(0, 500),
      xml,
      urls,
      sitemap_type
    }
  }
];

const site_url = $json.site_url || '';
const project_name = $json.project_name || '';
const urls = $json.urls || [];

return urls.map(url => ({
  json: {
    site_url,
    project_name,
    original_url: url,
    sitemap_url: url,
    looks_like_child_sitemap:
      String(url).toLowerCase().startsWith('http') &&
      String(url).toLowerCase().includes('sitemap') &&
      String(url).toLowerCase().endsWith('.xml')
  }
})).filter(item => item.json.looks_like_child_sitemap);

return items.flatMap(item => {
  const xml = item.json.body || item.json.data || item.json.response || '';

  const site_url =
    item.json.site_url ||
    $('On form submission').first().json.site_url ||
    '';

  const project_name =
    item.json.project_name ||
    $('On form submission').first().json.project_name ||
    '';

  const sitemap_url = item.json.sitemap_url || '';

  if (!xml || typeof xml !== 'string') return [];

  const matches = [...xml.matchAll(/<loc>(.*?)<\/loc>/gsi)];
  const urls = matches.map(m => m[1].trim());

  return urls.map(url => ({
    json: {
      site_url,
      project_name,
      source: 'sitemap_child',
      sitemap_url,
      url
    }
  }));
});

const blockedParts = [
  '/wp-admin/',
  '/feed',
  '/tag/',
  '/author/',
  '/cart',
  '/checkout',
  '/my-account',
  '.jpg',
  '.jpeg',
  '.png',
  '.gif',
  '.webp',
  '.svg',
  '.pdf',
  '.zip'
];

const out = [];

for (const item of items) {
  const site_url = String(
    item.json.site_url ||
    $('On form submission').first().json.site_url ||
    ''
  ).trim();

  const project_name = String(
    item.json.project_name ||
    $('On form submission').first().json.project_name ||
    ''
  ).trim();

  const source = String(item.json.source || 'unknown').trim();

  let url = String(item.json.url || '').trim();

  if (!site_url || !url) continue;

  if (url.startsWith('/')) {
    url = site_url.replace(/\/$/, '') + url;
  }

  if (!/^https?:\/\//i.test(url)) continue;

  const clean = url.toLowerCase();

  const sourceHost = site_url
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split('/')[0]
    .toLowerCase();

  const urlHost = url
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split('/')[0]
    .toLowerCase();

  if (urlHost !== sourceHost) continue;
  if (blockedParts.some(part => clean.includes(part))) continue;

  out.push({
    json: {
      site_url,
      project_name,
      source,
      url
    }
  });
}

return out;

const site_url = $json.site_url || '';
const project_name = $json.project_name || '';
const urls = $json.urls || [];

return urls
  .filter(url => typeof url === 'string' && url.startsWith('http'))
  .map(url => ({
    json: {
      site_url,
      project_name,
      source: 'sitemap_direct',
      url
    }
  }));

const html =
  $json.data ||
  $json.body ||
  $json.response ||
  '';

const site_url =
  $json.site_url ||
  $('On form submission').first().json.site_url ||
  '';

const project_name =
  $json.project_name ||
  $('On form submission').first().json.project_name ||
  '';

if (!html || typeof html !== 'string') {
  return [
    {
      json: {
        site_url,
        project_name,
        source: 'homepage_links',
        debug: 'No HTML received in body/data/response',
        urls: []
      }
    }
  ];
}

const matches = [...html.matchAll(/href=["'](https?:\/\/[^"'#]+|\/[^"'#]+)["']/gi)];
const rawUrls = matches.map(m => m[1].trim());

const normalizedUrls = rawUrls.map(url => {
  if (url.startsWith('http')) return url;
  return site_url.replace(/\/$/, '') + (url.startsWith('/') ? url : '/' + url);
});

const uniqueUrls = [...new Set(normalizedUrls)];
const filtered = uniqueUrls.filter(u =>
  u.includes(site_url.replace(/^https?:\/\//, ''))
);

return [
  {
    json: {
      site_url,
      project_name,
      source: 'homepage_links',
      urls: filtered
    }
  }
];

const seen = new Set();
const out = [];

for (const item of items) {
  const site_url = (item.json.site_url || '').trim();
  const project_name = (item.json.project_name || '').trim();
  const source = (item.json.source || 'unknown').trim();

  let url = (item.json.url || '').trim();
  if (!url) continue;

  // нормализация относительных ссылок
  if (url.startsWith('/')) {
    url = site_url.replace(/\/$/, '') + url;
  }

  if (!/^https?:\/\//i.test(url)) continue;

  // чистим якоря и слеш
  const normalized = url
    .replace(/#.*$/, '')
    .replace(/\/$/, '');

  const key = normalized.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  // приоритет услуг
  const priority =
    normalized.includes('/product') ||
    normalized.includes('/service') ||
    normalized.includes('/services') ||
    normalized.includes('/poslugi') ||
    normalized.includes('/category')
      ? 1
      : 0;

  out.push({
    json: {
      site_url,
      project_name,
      source,
      url: normalized,
      priority
    }
  });
}

return out;

const seen = new Set();
const result = [];

for (const item of items) {
  const url = (item.json.url || '').trim();

  if (!url) {
    result.push(item);
    continue;
  }

  if (!seen.has(url)) {
    seen.add(url);
    result.push(item);
  }
}

return result;

return items.map(item => {
  const text = (item.json.raw_content || '')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    json: {
      ...item.json,
      content_cleaned: text,
      clean_length: text.length
    }
  };
});

return items.filter(item => {
  const text = item.json.content_cleaned || '';
  return text.length > 100;
});

const seen = new Set();
const result = [];

for (const item of items) {
  const text = String(item.json.content_cleaned || '').trim();
  const url = String(item.json.url || '').trim();
  const source = String(item.json.source || '').trim();
  const site_url = String(item.json.site_url || '').trim();
  const project_name = String(item.json.project_name || '').trim();

  if (!text) continue;

  const key = text.slice(0, 300).toLowerCase();

  if (seen.has(key)) continue;
  seen.add(key);

  result.push({
    json: {
      ...item.json,
      text,
      url,
      source,
      site_url,
      project_name
    }
  });
}

return result;

function extractTitle(text, url) {
  if (!text) return '';

  const cleaned = text
    .replace(/\u00a0/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const parts = cleaned
    .split(/[\n\.]/)
    .map(s => s.trim())
    .filter(Boolean);

  for (const line of parts.slice(0, 10)) {
    if (line.length >= 8 && line.length <= 120 && !/^skip to/i.test(line)) {
      return line;
    }
  }

  const slug = (url || '')
    .replace(/\/$/, '')
    .split('/')
    .pop() || '';

  return slug.replace(/[-_]/g, ' ').trim();
}

const formSiteUrl = String($('On form submission').first().json.site_url || '').trim();
const formProjectName = String($('On form submission').first().json.project_name || '').trim();

return items.map(item => {
  const site_url = String(item.json.site_url || formSiteUrl || '').trim();
  const project_name = String(item.json.project_name || formProjectName || '').trim();
  const url = String(item.json.url || '').trim();

  const source =
    String(item.json.source || '').trim() ||
    (url.includes('/product') ? 'product_page' :
     url.includes('/service') ? 'service_page' :
     url.includes('/category') ? 'category_page' :
     'page');

  const content = String(
    item.json.content_cleaned ||
    item.json.text ||
    item.json.raw_content ||
    ''
  ).trim();

  const title = extractTitle(content, url);

  const metadata = {
    site_url,
    project_name,
    source,
    url,
    title
  };

  const document_text = [
    `Site: ${site_url}`,
    `Project: ${project_name}`,
    `Source: ${source}`,
    `URL: ${url}`,
    title ? `Title: ${title}` : '',
    '',
    content
  ].filter(Boolean).join('\n');

  return {
    json: {
      site_url,
      project_name,
      source,
      url,
      title,
      content,
      metadata,
      document_text
    }
  };
});

const items = $input.all();

items.sort((a, b) => (b.json.priority || 0) - (a.json.priority || 0));

return items;

